using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluation;

[TestClass]
public class EvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static IChatClient _evaluatorClient = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();
        _evaluatorClient = _chatClient;
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    [TestMethod]
    public async Task Greeting_IsCoherentAndRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how are you?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
        };

        var result = await EvaluateAsync(messages, evaluators);

        AssertMetricAboveThreshold(result, "Coherence", 3.0);
        AssertMetricAboveThreshold(result, "Relevance", 3.0);
    }

    [TestMethod]
    public async Task FactualQuestion_IsGroundedAndRelevant()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new GroundednessEvaluator(),
        };

        var result = await EvaluateAsync(messages, evaluators);

        AssertMetricAboveThreshold(result, "Coherence", 4.0);
        AssertMetricAboveThreshold(result, "Relevance", 4.0);
        AssertMetricAboveThreshold(result, "Groundedness", 3.0);
    }

    [TestMethod]
    public async Task MultiTurn_MaintainsContext()
    {
        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice.")
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));
        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
        };

        var result = await EvaluateAsync(messages, evaluators);

        AssertMetricAboveThreshold(result, "Coherence", 4.0);
        AssertMetricAboveThreshold(result, "Relevance", 4.0);
    }

    private async Task<EvaluationResult> EvaluateAsync(
        IList<ChatMessage> messages,
        IEnumerable<IEvaluator> evaluators)
    {
        var result = new EvaluationResult();

        foreach (var evaluator in evaluators)
        {
            var evalResult = await evaluator.EvaluateAsync(messages, _evaluatorClient);

            foreach (var kvp in evalResult)
            {
                result.Add(kvp.Key, kvp.Value);
            }
        }

        return result;
    }

    private static void AssertMetricAboveThreshold(
        EvaluationResult result,
        string metricName,
        double threshold)
    {
        Assert.IsTrue(
            result.TryGetNumericMetric(metricName, out var metric),
            $"Metric '{metricName}' not found in evaluation result.");

        Assert.IsTrue(
            metric.Value >= threshold,
            $"Metric '{metricName}' scored {metric.Value}, expected >= {threshold}.");
    }
}

